315	/// Validates an RFC3339 timestamp in UTC:
316	/// `YYYY-MM-DD'T'HH:mm:SS` optionally followed by one or more fractional
317	/// digits after a dot, terminated by exactly `Z` or `+00:00`. The calendar
318	/// date and wall-clock ranges are verified against the Gregorian calendar
319	/// (so e.g. `2026-02-30` is rejected); `-00:00`, other offsets, and a
320	/// missing zone are rejected.
321	private func isValidTimestamp(_ value: String) -> Bool {
322	    let scalars = Array(value.unicodeScalars)
323	
324	    func digit(at index: Int) -> Int? {
325	        guard index < scalars.count, case let s = scalars[index],
326	              ("0"..."9").contains(s) else { return nil }
327	        return Int(s.value - Unicode.Scalar("0").value)
328	    }
329	    func fixed(_ position: Int, _ count: Int) -> Int? {
330	        var number = 0
331	        for offset in 0..<count {
332	            guard let d = digit(at: position + offset) else { return nil }
333	            number = number * 10 + d
334	        }
335	        return number
336	    }
337	    func isScalar(_ character: Unicode.Scalar, at index: Int) -> Bool {
338	        index < scalars.count && scalars[index] == character
339	    }
340	
341	    // yyyy-MM-dd'T'HH:mm:ss — fixed positions through second 18.
342	    guard scalars.count >= 20,
343	          isScalar("-", at: 4), isScalar("-", at: 7), isScalar("T", at: 10),
344	          isScalar(":", at: 13), isScalar(":", at: 16)
345	    else {
346	        return false
347	    }
348	    guard let year = fixed(0, 4),
349	          let month = fixed(5, 2),
350	          let day = fixed(8, 2),
351	          let hour = fixed(11, 2),
352	          let minute = fixed(14, 2),
353	          let second = fixed(17, 2),
354	          (1...12).contains(month), (1...31).contains(day),
355	          (0...23).contains(hour),
356	          (0...59).contains(minute), (0...59).contains(second)
357	    else {
358	        return false
359	    }
360	
361	    // Optional fractional part: a dot followed by at least one digit.
362	    var index = 19
363	    if isScalar(".", at: index) {
364	        index += 1
365	        let fractionStart = index
366	        while index < scalars.count, ("0"..."9").contains(scalars[index]) {
367	            index += 1
368	        }
369	        guard index > fractionStart else { return false }
370	    }
371	
372	    // Required UTC zone: exactly "Z" or "+00:00".
373	    if isScalar("Z", at: index) {
374	        index += 1
375	    } else if isScalar("+", at: index),
376	              isScalar("0", at: index + 1), isScalar("0", at: index + 2),
377	              isScalar(":", at: index + 3),
378	              isScalar("0", at: index + 4), isScalar("0", at: index + 5) {
379	        index += 6
380	    } else {
381	        return false
382	    }
383	    guard index == scalars.count else { return false }
384	
385	    // Verify the date against the real Gregorian calendar by round-tripping
386	    // the components (catches leap-year and impossible-day errors).
387	    var calendar = Calendar(identifier: .gregorian)
388	    calendar.timeZone = TimeZone(secondsFromGMT: 0)!
389	    var components = DateComponents()
390	    components.year = year
391	    components.month = month
392	    components.day = day
393	    components.hour = hour
394	    components.minute = minute
395	    components.second = second
396	    guard let date = calendar.date(from: components) else { return false }
397	    let roundTrip = calendar.dateComponents(
398	        [.year, .month, .day, .hour, .minute, .second], from: date)
399	    return roundTrip.year == year
400	        && roundTrip.month == month
401	        && roundTrip.day == day
402	        && roundTrip.hour == hour
403	        && roundTrip.minute == minute
404	        && roundTrip.second == second
405	}
