486	private func renderSnapshot(records: [FileRecord], capturedAt: String) -> String {
487	    var output = "{\"version\":1,\"capturedAt\":\(jsonEscape(capturedAt)),\"files\":["
488	    output += records.map { record in
489	        "{\"path\":\(jsonEscape(record.path)),"
490	            + "\"sha256\":\(jsonEscape(record.sha256)),"
491	            + "\"size\":\(record.size)}"
492	    }.joined(separator: ",")
493	    output += "]}"
494	    return output
495	}
