512	private func isPath(_ path: String, inside ancestor: String) -> Bool {
513	    let ancestorComponents = (ancestor as NSString).pathComponents
514	    let pathComponents = (path as NSString).pathComponents
515	    return pathComponents.count >= ancestorComponents.count
516	        && Array(pathComponents.prefix(ancestorComponents.count)) == ancestorComponents
517	}
