519	private enum PublishError: Error {
520	    case destinationExists
521	    case io(String)
522	}
523	
524	/// Writes `json` to a staging file in the destination's own directory and
525	/// publishes it with `link(2)`, which fails with EEXIST instead of ever
526	/// overwriting an existing destination. The staging file is removed on every
527	/// failure path.
528	private func publishSnapshot(json: String, to snapshotPath: String) throws {
529	    let bytes = Data(json.utf8)
530	    let snapshotURL = URL(fileURLWithPath: snapshotPath)
531	    let parentPath = normalizedRoot(snapshotURL.deletingLastPathComponent().path)
532	    let tempName = String(
533	        format: ".macvault-snapshot.%d.%016llx.tmp",
534	        ProcessInfo.processInfo.processIdentifier,
535	        UInt64.random(in: 0...UInt64.max))
536	    let tempPath = (parentPath as NSString).appendingPathComponent(tempName)
537	
538	    let fd = open(tempPath, O_CREAT | O_EXCL | O_WRONLY, 0o644)
539	    guard fd >= 0 else {
540	        throw PublishError.io(
541	            "cannot create staging file: \(String(cString: strerror(errno)))")
542	    }
543	
544	    do {
545	        var offset = 0
546	        while offset < bytes.count {
547	            let written = bytes.withUnsafeBytes { rawBuffer -> Int in
548	                write(fd, rawBuffer.baseAddress!.advanced(by: offset), bytes.count - offset)
549	            }
550	            if written < 0 {
551	                if errno == EINTR { continue }
552	                throw PublishError.io("staging write failed: \(String(cString: strerror(errno)))")
553	            }
554	            offset += written
555	        }
556	        if fsync(fd) != 0 {
557	            throw PublishError.io("staging sync failed: \(String(cString: strerror(errno)))")
558	        }
559	        if close(fd) != 0 {
560	            throw PublishError.io("staging close failed: \(String(cString: strerror(errno)))")
561	        }
562	    } catch {
563	        close(fd)
564	        unlink(tempPath)
565	        throw error
566	    }
567	
568	    if link(tempPath, snapshotPath) != 0 {
569	        if errno == EEXIST {
570	            unlink(tempPath)
571	            throw PublishError.destinationExists
572	        }
573	        let message = "cannot publish snapshot: \(String(cString: strerror(errno)))"
574	        unlink(tempPath)
575	        throw PublishError.io(message)
576	    }
577	    unlink(tempPath)
578	}
